TRACKING = 1.3  # inter-glyph gap in glyph units


def text_strokes(
    text: str,
    origin: tuple[float, float],
    size: float,
    angle_deg: float = 0.0,
) -> list[list[tuple[float, float]]]:
    """Render ``text`` as page-space polylines.

    ``origin`` is the baseline start in page coordinates (PDF, y down),
    ``size`` is the cap height in points.
    """
    import math

    unit = size / CAP
    rad = math.radians(angle_deg)
    ca, sa = math.cos(rad), math.sin(rad)
    ox, oy = origin
    out: list[list[tuple[float, float]]] = []
    pen = 0.0
    for ch in text:
        adv, strokes = GLYPHS.get(ch, GLYPHS[" "])
        for stroke in strokes:
            poly: list[tuple[float, float]] = []
            for gx, gy in stroke:
                lx = (pen + gx) * unit
                ly = gy * unit
                # rotate in a y-up frame, then flip to PDF's y-down page space
                rx = lx * ca - ly * sa
                ry = lx * sa + ly * ca
                poly.append((ox + rx, oy - ry))
            out.append(poly)
        pen += adv + TRACKING
    return out


def text_advance(text: str, size: float) -> float:
    unit = size / CAP
    pen = 0.0
    for ch in text:
        adv, _ = GLYPHS.get(ch, GLYPHS[" "])
        pen += adv + TRACKING
    return max(0.0, pen - TRACKING) * unit
